test "t0" {
    assert (get_all_species_alive_area({"A": 1, "B": 1, "C": 0}, "A") == "A");;
}

test "t1" {
    assert (get_all_species_alive_area({"A": 1, "B": 0, "C": 0}, "A") == "A");;
}

test "t2" {
    assert (get_all_species_alive_area({"A": 1, "B": 1, "C": 0}, "B") == "B");;
}

test "t3" {
    assert (get_all_species_alive_area({"A": 0, "B": 1, "C": 0}, "B") == "B");;
}
